import{metro,patcher}from"@vendetta";const GatewayConnection=metro.findByProps("getGatewayConnection","isSessionReady");let unpatch;export default{onLoad:()=>{if(GatewayConnection){unpatch=patcher.after("getGatewayConnection",GatewayConnection,(args,res)=>{if(res&&res.properties){res.properties["$os"]="Windows";res.properties["$browser"]="Discord Client";res.properties["$device"]="discord-desktop";res.properties["client_info"]={os:"Windows",client:"desktop"};}return res;});}},onUnload:()=>{if(typeof unpatch==="function")unpatch();}};
